// Material code: runs once per hit (cheap), after the fields above are put into m.
//   m        the Material2 to change -- m.baseColor, m.roughness, m.metallic, m.emissive, ...
//   p, n     the hit point and surface normal, world space;  C  the Hit
//   p_local  the hit in the object's own frame, so a pattern moves with the object
//            (costs one extra SDF evaluation per hit on this material)
//   your own parameters (+ in the parameters header) by name, e.g. a colour stripe
// e.g. a checker fixed in the world:
//   m.baseColor = mix(m.baseColor, VEC3(0.05), step(0.0, sin(p.x * 3.0) * sin(p.y * 3.0) * sin(p.z * 3.0)));
// e.g. stripes that travel with the object:
//   m.roughness = step(0.5, fract(p_local.x * 4.0)) * 0.6;
// e.g. with a number width and a colour stripe added with +:
//   m.baseColor = mix(m.baseColor, stripe, step(fract(p.x / width), 0.5));

// Brushed along the object's own x: the strokes turn with the object (R_local).
// Positive anisotropy is smooth along the strokes and rough across them, so the
// highlight is drawn out ACROSS the strokes, as on real brushed metal.
m.tangent = grainAlong(R_local, VEC3(1.0, 0.0, 0.0));
// The lines: grooves of different depths, each a little rougher or smoother and darker or
// lighter than the next. streakWidth and streakLength in mm, real size whatever the scene's
// unit or the object's scale -- so on a metre-sized object seen whole they are too fine to see,
// as in life. streaks is how much the lines differ, 0 to 1.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let s = streaksAlong(q, VEC3(1.0, 0.0, 0.0), streakWidth, streakLength);
m.roughness = m.roughness * mix(1.0 - 0.6 * streaks, 1.0 + 0.6 * streaks, s);
m.baseColor = m.baseColor * mix(1.0 - 0.1 * streaks, 1.0, s);

